const body = $input.first().json.body || $input.first().json;
const to = String(body.to || '').replace(/\D/g, '');
const message = String(body.message || '');

if (!to || !message) {
  return [{ json: { success: false, error: 'Missing to or message' } }];
}

// Normalize to international format (add country code if missing)
const phone = to.startsWith('92') ? to : (to.startsWith('0') ? '92' + to.slice(1) : '92' + to);

return [{ json: { to: phone, message, source: body.source || 'jarvisx' } }];

// ── Twilio WhatsApp Send ─────────────────────────────────────────────────
// Requires: TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, TWILIO_WHATSAPP_FROM
// Set these as n8n credentials or environment variables.
//
// If you don't have Twilio, replace this block with your WhatsApp Business
// API provider (e.g., 360Dialog, Meta Cloud API).

const item = $input.first().json;
const to = item.to;
const message = item.message;

const accountSid = $env.TWILIO_ACCOUNT_SID;
const authToken  = $env.TWILIO_AUTH_TOKEN;
const from       = $env.TWILIO_WHATSAPP_FROM || 'whatsapp:+14155238886'; // Twilio sandbox default

if (!accountSid || !authToken) {
  return [{ json: {
    success: false,
    error: 'Set TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN as n8n environment variables.',
    hint: 'Go to n8n Settings → Environment Variables and add TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, TWILIO_WHATSAPP_FROM'
  }}];
}

const url = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
const body = new URLSearchParams({
  From: from,
  To: `whatsapp:+${to}`,
  Body: message,
}).toString();

const credentials = Buffer.from(`${accountSid}:${authToken}`).toString('base64');

const response = await fetch(url, {
  method: 'POST',
  headers: {
    'Authorization': `Basic ${credentials}`,
    'Content-Type': 'application/x-www-form-urlencoded',
  },
  body,
});

const result = await response.json();

if (response.ok) {
  return [{ json: {
    success: true,
    message: `WhatsApp message sent to +${to}`,
    sid: result.sid,
    status: result.status,
  }}];
} else {
  return [{ json: {
    success: false,
    error: result.message || 'Twilio error',
    code: result.code,
    details: result,
  }}];
}
